/* دروس برمِج التفاعلية */
window.BARMEJ_LESSONS=[
{id:1,title:"أهلاً بالبرمجة",text:`<p>البرمجة إنك تدّي أوامر للكمبيوتر بلغة يفهمها. في <b>برمِج</b> بتكتب أوامرك بالعربي!</p>
<p>أول أمر: <code>اطبع</code> — بيطبع أي حاجة على الشاشة.</p>
<pre>اطبع "أهلاً بالعالم"</pre>
<p><b>مهمتك:</b> اطبع جملة فيها اسمك.</p>`,
starter:'اطبع "أهلاً بالعالم"',
check(out){ return out.length>0 && /[؀-ۿ]/.test(out[0]) ? null : 'لازم تطبع جملة عربية. جرّب: اطبع "اسمك هنا"'; }},
{id:2,title:"المتغيرات",text:`<p>المتغير زي علبة بتحط فيها قيمة وتستعملها بعدين. بنعمله بكلمة <code>خلي</code>:</p>
<pre>خلي اسم = "محمد"
خلي عمر = ٢٧
اطبع "أنا " + اسم
اطبع عمر + ١</pre>
<p>لاحظ: الأرقام العربية (١٢٣) شغالة عادي!</p>
<p><b>مهمتك:</b> اعمل متغيرين واطبع ناتج جمعهم.</p>`,
starter:'خلي أ = ٥\nخلي ب = ٣\nاطبع أ + ب',
check(out){ const n=parseFloat(out[0]); return out.length===1 && !isNaN(n) ? null : 'المفروض سطر واحد فيه ناتج الجمع. مثال: خلي أ = ٥ ثم خلي ب = ٣ ثم اطبع أ + ب'; }},
{id:3,title:"الشروط — لو",text:`<p>البرنامج يقدر ياخد قرارات بـ<code>لو</code>:</p>
<pre>خلي درجة = ٨٥
لو درجة >= ٥٠ {
  اطبع "ناجح"
} وإلا {
  اطبع "راسب"
}</pre>
<p>وفي <code>وإلا لو</code> لشروط متعددة. المقارنات: <code>&gt; &lt; == != &gt;= &lt;=</code></p>
<p><b>مهمتك:</b> اختبر لو رقم أكبر من ١٠ واطبع "كبير" أو "صغير".</p>`,
starter:'خلي رقم = ١٥\nلو رقم > ١٠ {\n  اطبع "كبير"\n} وإلا {\n  اطبع "صغير"\n}',
check(out){ return out.length===1 && (out[0]==='كبير'||out[0]==='صغير') ? null : 'المفروض تطبع «كبير» أو «صغير» حسب الرقم.'; }},
{id:4,title:"التكرار — كرر وطالما",text:`<p>عايز تنفذ أمر ١٠٠ مرة؟ متكتبهوش ١٠٠ مرة! استخدم <code>كرر</code>:</p>
<pre>كرر ٥ {
  اطبع "نمرة " + عداد
}</pre>
<p><code>عداد</code> متغير جاهز جوه التكرار. وفيه <code>طالما</code> اللي بتلف طالما الشرط متحقق.</p>
<p><b>مهمتك:</b> اطبع الأرقام من ١ لـ ٥ باستخدام كرر.</p>`,
starter:'كرر ٥ {\n  اطبع عداد\n}',
check(out){ return out.join(',')==='1,2,3,4,5' ? null : 'المفروض الخرج يكون الأرقام 1 لحد 5 كل رقم في سطر. استخدم عداد.'; }},
{id:5,title:"القوائم",text:`<p>القائمة بتجمع قيم كتير في متغير واحد:</p>
<pre>خلي ألعاب = ["كورة"، "شطرنج"، "بلياردو"]
اطبع ألعاب[٠]
أضف(ألعاب، "طاولة")
اطبع طول(ألعاب)</pre>
<p>الفهرس بيبدأ من صفر. ومع <code>لكل</code> تلف على كل عنصر:</p>
<pre>لكل لعبة في ألعاب {
  اطبع لعبة
}</pre>
<p><b>مهمتك:</b> اعمل قائمة أكل واطبع كل صنف بـ لكل.</p>`,
starter:'خلي أكل = ["كشري"، "فول"، "طعمية"]\nلكل صنف في أكل {\n  اطبع صنف\n}',
check(out){ return out.length>=2 && out.every(x=>/[؀-ۿ]/.test(x)) ? null : 'اعمل قائمة ولف عليها بـ لكل واطبع كل عنصر في سطر.'; }},
{id:6,title:"الدوال",text:`<p>الدالة كود بتكتبه مرة وتستدعيه وقت ما تحب:</p>
<pre>دالة مساحة(طول، عرض) {
  ارجع طول * عرض
}
اطبع مساحة(٥، ٣)</pre>
<p><code>ارجع</code> بترجع النتيجة لمين استدعى الدالة.</p>
<p><b>مهمتك:</b> اكتب دالة <code>مربع</code> ترجع مربع الرقم واطبع مربع ٧.</p>`,
starter:'دالة مربع(س) {\n  ارجع س * س\n}\nاطبع مربع(٧)',
check(out){ return out.length===1 && out[0]==='49' ? null : 'اكتب دالة مربع ترجع س * س واطبع مربع(٧) — النتيجة 49.'; }},
{id:7,title:"القواميس والمدخلات",text:`<p>القاموس بيربط مفاتيح بقيم:</p>
<pre>خلي لاعب = {اسم: "علي"، نقاط: ١٠٠}
اطبع لاعب.اسم
لاعب.نقاط = لاعب.نقاط + ٥٠</pre>
<p>و<code>اسأل</code> بتاخد إدخال من المستخدم:</p>
<pre>خلي اسم = اسأل("إيه اسمك؟")
اطبع "أهلاً " + اسم</pre>
<p><b>مهمتك:</b> اعمل قاموس فيه بياناتك واطبع قيمة منه.</p>`,
starter:'خلي أنا = {اسم: "ضيف"، مدينة: "القاهرة"}\nاطبع أنا.مدينة',
check(out){ return out.length>=1 && out[0].length>0 ? null : 'اعمل قاموس واطبع قيمة منه (مثال: اطبع أنا.مدينة).'; }},
{id:8,title:"مشروع: لعبة تخمين",text:`<p>يلا نجمع كل اللي اتعلمناه في لعبة! البرنامج يختار رقم ويدّيك تلميحات:</p>
<pre>خلي سر = عشوائي(١، ١٠)
خلي محاولات = ٣
طالما محاولات > ٠ {
  خلي ت = رقم(اسأل("خمن رقم من ١ لـ ١٠"))
  لو ت == سر {
    اطبع "صح! مبروك 🎉"
    قف
  } وإلا لو ت < سر {
    اطبع "أكبر من كده"
  } وإلا {
    اطبع "أصغر من كده"
  }
  محاولات = محاولات - ١
}</pre>
<p><b>مهمتك:</b> عدّل اللعبة: خليها ٥ محاولات واطبع رسالة خسارة لو خلصوا.</p>`,
starter:'خلي سر = عشوائي(١، ١٠)\nاطبع "أنا فكرت في رقم من ١ لـ ١٠"\nخلي ت = رقم(اسأل("خمينك؟"))\nلو ت == سر {\n  اطبع "مبروك!"\n} وإلا {\n  اطبع "غلط، كان " + سر\n}',
check(out){ return out.length>=1 ? null : 'شغّل اللعبة وجاوب على السؤال.'; }},
{id:9,title:"الرسم بالكود",text:`<p>برمِج فيها قلم بيرسم على لوحة! تحكم فيه بأوامر بسيطة:</p>
<pre>لون("أحمر")
سمك(٣)
كرر ٤ {
  قدم(١٢٠)
  يمين(٩٠)
}</pre>
<p>الأوامر: <code>قدم(مسافة)</code> <code>ورا(مسافة)</code> <code>يمين(زاوية)</code> <code>شمال(زاوية)</code> <code>لون("اسم")</code> <code>سمك(ن)</code> <code>دائرة(نصف)</code> <code>ارفع()</code> <code>انزل()</code> <code>اذهب(س،ص)</code></p>
<p><b>مهمتك:</b> ارسم مثلث (٣ أضلاع، زاوية ١٢٠).</p>`,
starter:'لون("ذهبي")\nسمك(٣)\nكرر ٣ {\n  قدم(١٥٠)\n  يمين(١٢٠)\n}',
check(out,ops){ const f=(ops||[]).filter(o=>o.op==='fd').length; return f>=3 ? null : 'ارسم ٣ خطوط على الأقل باستخدام قدم — جرّب الكود الجاهز ودوس شغّل.'; }},
{id:10,title:"مشروع: وردة هندسية",text:`<p>بالتكرار والزوايا تقدر ترسم أشكال مبهرة:</p>
<pre>كرر ١٨ {
  لون(عشوائي(["أحمر"، "وردي"، "بنفسجي"]))
  قدم(٧٠)
  دائرة(٤٥)
  ورا(٧٠)
  يمين(٢٠)
}</pre>
<p><b>مهمتك:</b> اعمل الشكل ده، وبعدين غيّر الألوان والزاوية وشوف النتيجة!</p>`,
starter:'كرر ١٨ {\n  لون(عشوائي(["أحمر"، "وردي"، "بنفسجي"]))\n  قدم(٧٠)\n  دائرة(٤٥)\n  ورا(٧٠)\n  يمين(٢٠)\n}',
check(out,ops){ const c=(ops||[]).filter(o=>o.op==='circle').length; return c>=10 ? null : 'المفروض ترسم ٣٦ دائرة — شغّل الكود الجاهز الأول وبعدين عدّل.'; }},
{id:11,title:"الوقت — استنى",text:`<p><code>استنى(عدد)</code> بيوقف البرنامج شوية (بالمللي ثانية — ١٠٠٠ يعني ثانية):</p>
<pre>اطبع "١"
استنى(١٠٠٠)
اطبع "٢"
استنى(١٠٠٠)
اطبع "انطلاق!"</pre>
<p>ده بيخلي البرنامج «حي» — عدادات، حركة، وألعاب. لاحظ إن الطباعة بتظهر أول بأول مش مرة واحدة في الآخر!</p>
<p><b>مهمتك:</b> اعمل عداد من ٣ لـ ١ بين كل رقم والتاني استنى(٥٠٠)، وبعدين اطبع "انطلاق!".</p>`,
starter:'خلي عد = ٣\nطالما عد > ٠ {\n  اطبع عد\n  استنى(٥٠٠)\n  عد = عد - ١\n}\nاطبع "انطلاق!"',
check(out){ return out.join(',')==='3,2,1,انطلاق!' ? null : 'المفروض الخرج: 3 ثم 2 ثم 1 ثم «انطلاق!».'; }},
{id:12,title:"الألعاب — مفتاح",text:`<p><code>مفتاح()</code> بترجع اسم المفتاح اللي مدوس عليه دلوقتي: <code>يمين</code>، <code>يسار</code>، <code>فوق</code>، <code>تحت</code>، <code>مسافة</code>… ولو مفيش حاجة مدوسة بترجع نص فاضي.</p>
<pre>خلي س = ٠
كرر ١٠٠ {
  لو مفتاح() == "يمين" { س = س + ٥ }
  استنى(٥٠)
}</pre>
<p>التركيبة السحرية للألعاب: حلقة + <code>مفتاح</code> + <code>استنى</code>. جرّب مثال «🐍 لعبة الثعبان»!</p>
<p><b>مهمتك:</b> الكود الجاهز بيعد اللي فات — شغّله ودوس يمين كذا مرة وشوف النتيجة.</p>`,
starter:'خلي س = ٠\nكرر ٢٠ {\n  لو مفتاح() == "يمين" { س = س + ٥ }\n  استنى(٥٠)\n}\nاطبع "تحركت: " + س',
check(out){ return out.length===1 && out[0].startsWith('تحركت:') ? null : 'المفروض تطبع «تحركت: » وقدامها رقم.'; }},
{id:13,title:"الدالة اللي بتنادي نفسها",text:`<p>الدالة تقدر تنادي <b>نفسها</b>! ده اسمه استدعاء ذاتي، وبيحل مسائل معقدة بسهولة:</p>
<pre>دالة مضروب(ن) {
  لو ن <= ١ { ارجع ١ }
  ارجع ن * مضروب(ن - ١)
}
اطبع مضروب(٥)   # 120</pre>
<p>القاعدة الذهبية: لازم حالة توقف (لو ن <= ١) وإلا هتلف للأبد!</p>
<p>وبالرسم بتطلع عجائب — جرّب مثال «🌳 شجرة فركتال».</p>
<p><b>مهمتك:</b> اكتب دالة <code>مجموع(ن)</code> بترجع ١+٢+…+ن بالاستدعاء الذاتي، واطبع مجموع(١٠) لازم تكون 55.</p>`,
starter:'دالة مجموع(ن) {\n  لو ن <= ٠ { ارجع ٠ }\n  ارجع ن + مجموع(ن - ١)\n}\nاطبع مجموع(١٠)',
check(out){ return out.length===1 && out[0]==='55' ? null : 'المفروض تطبع 55 — استخدم استدعاء ذاتي مع حالة توقف.'; }}
,
{id:14,title:"القواميس: بيانات بأسماء",text:`<p>القاموس بيخزن قيم <b>بأسمائها</b> مش بأرقامها:</p>
<pre>خلي طالب = {اسم: "سارة"، سن: ١٢، درجة: ٩٥}
اطبع طالب.اسم      # سارة
اطبع طالب.درجة     # 95</pre>
<p>تقدر تضيف وتغيّر: <code>طالب.مدرسة = "النور"</code>. والدوال <code>مفاتيح(ق)</code> و<code>قيم(ق)</code> بترجع القوائم.</p>
<p>ولفّ على القاموس بـ<code>لكل م في مفاتيح(قاموس)</code>.</p>
<p><b>مهمتك:</b> اعمل قاموس <code>درجات</code> فيه <code>{"أحمد": ٩٠، "سارة": ٩٥، "ليلى": ٨٨}</code> واطبع درجة سارة (لازم 95).</p>`,
starter:'خلي درجات = {"أحمد": ٩٠، "سارة": ٩٥، "ليلى": ٨٨}\n# اطبع درجة سارة هنا',
check(out){ return out.length===1 && out[0]==='95' ? null : 'المفروض تطبع 95 — استخدم درجات.سارة أو درجات["سارة"].'; }},
{id:15,title:"النصوص: حروف وكلمات",text:`<p>النص زي القائمة: <code>طول("برمجة")</code> = 5، و<code>كلمة[٠]</code> أول حرف.</p>
<pre>اطبع حروف("قمر")          # ["ق","م","ر"]
اطبع اعكس("قمر")          # رمق
اطبع فصل("أنا بحب البرمجة"، " ")   # قائمة كلمات
اطبع وصل(["أ"، "ب"، "ج"]، "-")     # أ-ب-ج</pre>
<p>وده مفيد للألعاب الكلامية زي مثال «🎯 خمّن الكلمة».</p>
<p><b>مهمتك:</b> اطبع كلمة "برمجة" معكوسة بحرف <code>اعكس</code> (لازم تطلع ةجمرب).</p>`,
starter:'# اعكس النص واطبعه',
check(out){ return out.length===1 && out[0]==='ةجمرب' ? null : 'المفروض تطبع ةجمرب — جرّب اطبع اعكس("برمجة").'; }}
,
{id:16,title:"الأخطاء: جرّب ولو_خطأ",text:`<p>أحيانًا البرنامج بيقابل مشكلة (زي القسمة على صفر). بدل ما يقف، تقدر <b>تمسك</b> الخطأ:</p>
<pre>جرّب {
  اطبع ١٠ / ٠
} لو_خطأ سبب {
  اطبع "حصل خطأ: " + سبب
}
اطبع "كملنا!"</pre>
<p>الكود اللي جوه <code>جرّب</code> بيتنفذ عادي، ولو حصل خطأ بيتنفذ كود <code>لو_خطأ</code> ورسالة الخطأ بتتحط في المتغير (<code>سبب</code>).</p>
<p><b>مهمتك:</b> اقسم ٥ على ٠ جوه جرّب، وفي لو_خطأ اطبع كلمة <code>ممنوع</code>.</p>`,
starter:'# اكتب جرّب هنا',
check(out){ return out.length===1 && out[0]==='ممنوع' ? null : 'المفروض يطبع ممنوع بس — حط ٥ / ٠ جوه جرّب واطبع "ممنوع" في لو_خطأ.'; }}
,
{id:17,title:"أدوات القوائم: أول وآخر وفريد",text:`<p>في أدوات سريعة للقوائم والنصوص:</p>
<pre>خلي ق = [٣، ١، ٣، ٢، ١]
اطبع أول(ق)            # ٣
اطبع آخر(ق)            # ١
اطبع فريد(ق)           # بدون تكرار
اطبع عدد_مرات(ق، ٣)    # ٢</pre>
<p>كلهم بيشتغلوا على النصوص كمان (<code>أول("قمر")</code> بتدي ق).</p>
<p><b>مهمتك:</b> عندك القائمة <code>[٥، ٥، ٧، ٥، ٧، ٩]</code>. اطبع كام مرة ظهر الرقم ٥.</p>`,
starter:'خلي ق = [٥، ٥، ٧، ٥، ٧، ٩]\n# اطبع عدد مرات ٥',
check(out){ return out.length===1 && out[0]==='3' ? null : 'المفروض تطبع ٣ — استخدم عدد_مرات(ق، ٥).'; }}
,
{id:18,title:"الأصناف: صنف وجديد",text:`<p>الصنف قالب بتعمل منه كائنات (زي لاعب أو حساب). جواه دوال، والدالة <code>بناء</code> بتتنفذ أول ما تعمل كائن بـ <code>جديد</code>. وجوه الدوال <code>هذا</code> يعني الكائن نفسه:</p>
<pre>صنف قطة {
  دالة بناء(اسم) { هذا.اسم = اسم }
  دالة تكلم() { اطبع هذا.اسم + " بتقول مياو" }
}
خلي ق = جديد قطة("لولو")
ق.تكلم()</pre>
<p>وتقدر تورّث: <code>صنف كلب يرث حيوان { ... }</code> والصنف الابن بيناديه على الأب بـ <code>الأب.اسم_الدالة()</code>.</p>
<p><b>مهمتك:</b> اعمل صنف <code>عداد</code> فيه <code>بناء()</code> بيخلي <code>هذا.قيمة = ٠</code> ودالة <code>زود()</code> بتزود قيمة ١. اعمل كائن، نادي زود() ثلاث مرات، واطبع قيمته (المفروض ٣).</p>`,
starter:'# اكتب الصنف هنا',
check(out){ return out.length===1 && out[0]==='3' ? null : 'المفروض تطبع ٣ — صنف عداد، بناء بيصفّر، وزود() بتزود ١، وناديها ٣ مرات.'; }}
,
{id:19,title:"دوال بتاخد دوال: خريطة وصفّي واختزل",text:`<p>الدالة نفسها ممكن تتحط في متغير وتتبعت لدالة تانية. وتقدر تكتب دالة بدون اسم: <code>دالة(س): س * ٢</code> أو <code>دالة(س) { ارجع س * ٢ }</code>.</p>
<pre>خلي ق = [١، ٢، ٣، ٤]
اطبع خريطة(ق، دالة(س): س * ٢)        # [٢، ٤، ٦، ٨]
اطبع صفّي(ق، دالة(س): س > ٢)         # [٣، ٤]
اطبع اختزل(ق، دالة(أ، ب): أ + ب، ٠)   # ١٠</pre>
<p><code>خريطة</code> بتحوّل كل عنصر، <code>صفّي</code> بتفضل اللي يحقق الشرط، و<code>اختزل</code> بتجمّع القائمة في قيمة واحدة. وكمان: <code>جد</code> <code>أي</code> <code>كل</code> <code>رتب_حسب</code>.</p>
<p><b>مهمتك:</b> من القائمة <code>[١، ٢، ٣، ٤، ٥، ٦]</code> هات مربعات الأرقام الزوجية بس (٤ و ١٦ و ٣٦) واطبعها كقائمة.</p>`,
starter:'خلي ق = [١، ٢، ٣، ٤، ٥، ٦]\n# صفّي الزوجي وبعدين خريطة للمربعات',
check(out){ return out.length===1 && out[0].replace(/\s/g,'')==='[4،16،36]' ? null : 'المفروض يطبع [٤، ١٦، ٣٦] — صفّي(ق، دالة(س): س % ٢ == ٠) وبعدين خريطة بالتربيع.'; }}
,
{id:20,title:"المكتبات: استورد",text:`<p>بدل ما تكتب كل حاجة من الصفر، <code>استورد</code> بتجيب لك دوال جاهزة:</p>
<pre>استورد "رياضيات"
اطبع مضروب(٥)       # ١٢٠
اطبع قاسم_مشترك(٤٨، ١٨)  # ٦</pre>
<p>المكتبات: <b>رياضيات</b> (مضروب، أولي، فيبوناتشي، متوسط…)، <b>نصوص</b>، <b>قوائم</b>. وتقدر تعمل مكتبتك: احفظ برنامج باسم في «برامجي» واستورده بالاسم.</p>
<p><b>مهمتك:</b> استورد مكتبة «رياضيات» واطبع مضروب ٦ (المفروض ٧٢٠).</p>`,
starter:'# استورد المكتبة هنا',
check(out){ return out.length===1 && out[0]==='720' ? null : 'المفروض تطبع ٧٢٠ — استورد "رياضيات" وبعدين اطبع مضروب(٦).'; }},
{id:21,title:"الألعاب: مسافة وتصادم",text:`<p>أي لعبة محتاجة تعرف لو حاجتين لمسوا بعض. برمج فيه دوال جاهزة:</p>
<pre>اطبع مسافة(٠، ٠، ٣، ٤)                  # ٥
اطبع تصادم(٠، ٠، ٥، ٨، ٠، ٥)             # صحيح (الدايرتين لمسوا بعض)
اطبع داخل(٥، ٥، ٠، ٠، ١٠، ١٠)           # صحيح (النقطة جوه المستطيل)</pre>
<p>وارسم شخصياتك بالإيموجي: <code>رمز("🚀"، ٥٠)</code> و<code>خلفية("أسود")</code> في أول كل إطار. جرّب مثال «سفينة الفضاء».</p>
<p><b>مهمتك:</b> اطبع مسافة بين النقطتين (١، ١) و(٤، ٥) (المفروض ٥).</p>`,
starter:'# اطبع المسافة هنا',
check(out){ return out.length===1 && out[0]==='5' ? null : 'المفروض تطبع ٥ — اكتب اطبع مسافة(١، ١، ٤، ٥).'; }}
,
{id:22,title:"الموسيقى: لحن",text:`<p>برمج بيعزف! اكتب النوتات في نص: <code>دو ري مي فا صول لا سي</code>. العلامة <code>+</code> بتعلّي النوتة، <code>-</code> بتنزلها، <code>:٢</code> بتطوّلها، و<code>_</code> سكوت.</p>
<pre>لحن("دو مي صول مي+ صول+:2"، ٣٠٠)   # ٣٠٠ = مللي ثانية للنوتة</pre>
<p><b>مهمتك:</b> العب الأغنية الموجودة، واطبع عدد نوتاتها باستخدام <code>طول(فصل(أغنية، " "))</code> (المفروض ٤).</p>`,
starter:'خلي أغنية = "دو مي صول مي"\n# اعزفها واطبع عدد النوتات',
check(out){ return out.length===1 && out[0]==='4' ? null : 'المفروض تطبع ٤ — لحن(أغنية، ٣٠٠) وبعدين اطبع طول(فصل(أغنية، " ")).'; }}
,
{id:23,title:"شخصيات بالبكسل",text:`<p>ارسم شخصيتك في محرر 🎨 (فوق في الهيدر) وهيحطها لك في الكود كقائمة صفوف: كل رقم لون والنقطة شفاف. وبعدين <code>بكسلات</code> بترسمها مكان القلم:</p>
<pre>خلي قلب = [
  ".22.22.",
  "2222222",
  ".22222.",
  "..222..",
  "...2..."
]
ارفع()
اذهب(٠، ٠)
بكسلات(قلب، ٢٠)   # ٢٠ = حجم البكسل الواحد</pre>
<p>حرّك الشخصية بتغيير <code>اذهب</code> في كل إطار مع <code>خلفية("أسود")</code> و<code>استنى(٢٠)</code> وهتبقى لعبة.</p>
<p><b>مهمتك:</b> اعمل قائمة اسمها <code>شكل</code> فيها ٣ صفوف، واطبع عدد الصفوف (٣) باستخدام <code>طول</code>.</p>`,
starter:'# اعمل قائمة شكل فيها ٣ صفوف نصية',
check(out){ return out.length===1 && out[0]==='3' ? null : 'المفروض تطبع ٣ — خلي شكل = ["1.1"، ".1."، "1.1"] وبعدين اطبع طول(شكل).'; }}
,
{id:24,title:"عالم من بلاط",text:`<p>الألعاب الكبيرة بتتبني من خريطة: قائمة صفوف نصية، <code>#</code> جدار والنقطة فاضي. ارسمها بزر 🗺️ أو اكتبها بإيدك، وبعدين <code>خريطة_بلاط</code> بترسمها في نص اللوحة:</p>
<pre>خلي خريطة = [
  "####",
  "#..#",
  "####"
]
خريطة_بلاط(خريطة، ٤٠)</pre>
<p>ولو عايز تعرف في الخانة اللي عند نقطة معينة إيه، استخدم <code>بلاطة_عند(خريطة، حجم، س، ص)</code>. بترجّع <code>#</code> لو جدار، وده اللي بتعمل بيه تصادم:</p>
<pre>لو بلاطة_عند(خريطة، ٤٠، س، ص) == "#" { اطبع "خبطت في جدار" }</pre>
<p><b>مهمتك:</b> الخريطة <code>["#."، ".."]</code> حجم بلاطتها ١٠ ومنتصفها (٠،٠). اطبع إيه الموجود عند النقطة (-٥، -٥) (الركن العلوي الشمال).</p>`,
starter:'خلي خ = ["#."، ".."]\n# اطبع بلاطة_عند عند (-٥، -٥)',
check(out){ return out.length===1 && out[0]==='#' ? null : 'المفروض تطبع # — اطبع بلاطة_عند(خ، ١٠، -٥، -٥).'; }},
{id:25,title:"احفظ أرقامك القياسية",text:`<p>المتغيرات بتتمسح لما البرنامج يخلص. لو عايز لعبتك تفتكر أحسن نتيجة حتى بعد ما تقفل الصفحة، استخدم <code>احفظ</code> و<code>استرجع</code>:</p>
<pre>خلي أحسن = استرجع("نتيجتي"، ٠)   # ٠ لو مفيش حاجة محفوظة
لو ٥٠ > أحسن {
  احفظ("نتيجتي"، ٥٠)
  اطبع "رقم قياسي جديد!"
}</pre>
<p>تقدر تحفظ أرقام ونصوص وقوائم. الاسم (زي "نتيجتي") هو مفتاح الدرج اللي بتحط فيه القيمة. جرّب مثال "غزاة الأرقام" — بيحفظ أحسن نتيجة لوحده.</p>
<p><b>مهمتك:</b> احفظ الرقم ٧ تحت اسم "س" بـ <code>احفظ</code>، وبعدين اطبع <code>استرجع("س"، ٠)</code>.</p>`,
starter:'# احفظ ٧ تحت الاسم "س" وبعدين اطبع المسترجع',
check(out){ return out.length===1 && out[0]==='7' ? null : 'المفروض تطبع ٧ — احفظ("س"، ٧) وبعدها اطبع استرجع("س"، ٠).'; }},
{id:26,title:"لعبة متاهة كاملة",text:`<p>لعبة المتاهة فيها ٣ حاجات: خريطة، لاعب بيتحرك، وفحص جدار قبل كل خطوة. الفكرة: احسب المكان الجديد، وما تتحركش إلا لو <code>بلاطة_عند</code> مش جدار:</p>
<pre>خلي ن = س + ٣
لو بلاطة_عند(خريطة، ٣٦، ن، ص) != "#" {
  س = ن   # مفيش جدار، اتحرك
}</pre>
<p>اعمل كده للمحور الأفقي والرأسي كل واحد لوحده، فاللاعب ينزلق جنب الجدار بدل ما يقف. جرب مثال "مغامرة المتاهات" وارسم مراحلك بزر 🗺️.</p>
<p><b>مهمتك:</b> الخريطة <code>["..."، "#.."]</code> حجم بلاطتها ١٠ ومنتصفها (٠،٠). اطبع إيه الموجود عند النقطة (-١٠، ٥)، يعني الخانة التحتانية الشمال.</p>`,
starter:'خلي خ = ["..."، "#.."]\n# اطبع بلاطة_عند عند (-١٠، ٥)',
check(out){ return out.length===1 && out[0]==='#' ? null : 'المفروض تطبع # — اطبع بلاطة_عند(خ، ١٠، -١٠، ٥).'; }},
{id:27,title:"الجاذبية والسرعة",text:`<p>سر لعبة الطائر والقفز كلها سطرين: السرعة بتزيد بالجاذبية، والمكان بيزيد بالسرعة، وفي كل إطار:</p>
<pre>سرعة = سرعة + ٠.٧   # الجاذبية
ص = ص + سرعة        # الحركة</pre>
<p>وعشان يرفرف: لما تضغط حط السرعة قيمة سالبة (<code>سرعة = -٩</code>) فيطلع لفوق وبعدين الجاذبية ترجعه. جرب مثال "الطائر المغامر".</p>
<p><b>مهمتك:</b> ابدأ بـ <code>ص = ٠</code> و<code>سرعة = ٠</code>. كرر ٣ مرات: زوّد السرعة ٠.٥ وزوّد ص بالسرعة، واطبع ص كل مرة. (الناتج: ٠.٥ ثم ١.٥ ثم ٣)</p>`,
starter:'خلي ص = ٠\nخلي سرعة = ٠\n# كرر ٣ مرات',
check(out){ return out.join('|')==='0.5|1.5|3' ? null : 'المفروض يطبع ٠.٥ ثم ١.٥ ثم ٣ — جوه كرر ٣: سرعة = سرعة + ٠.٥ ثم ص = ص + سرعة ثم اطبع ص.'; }},
{id:28,title:"صيد الأخطاء (المُنقّح)",text:`<p>كل مبرمج بيقع في أخطاء، والمهم تعرف تصيدها. برمِج فيه ٣ أدوات:</p>
<ul><li>🔴 <b>نقطة توقف:</b> دوس على رقم أي سطر في المحرر، وبعدين دوس «خطوة بخطوة» والبرنامج هيقف عند السطر ده.</li>
<li>👣 <b>خطوة بخطوة:</b> بتنفّذ سطر سطر وبتشوف المتغيرات في اللوحة وهي بتتغير (اللي اتغيّر بيتلوّن).</li>
<li>🖨️ <b>اطبع:</b> أبسط طريقة، حط <code>اطبع</code> جوه الحلقة تشوف القيمة كل مرة.</li></ul>
<p><b>مهمتك:</b> البرنامج ده المفروض يجمع الأرقام من ١ لـ ٥ ويطبع <b>١٥</b> بس هو بيطبع ٥. جرّب «خطوة بخطوة» وراقب <code>مجموع</code>، وبعدين صلّح السطر الغلط.</p>`,
starter:'خلي مجموع = ٠\nكرر ٥، ر {\n  مجموع = ر   # فيه غلطة هنا!\n}\nاطبع مجموع',
check(out){ return out.join('|')==='15' ? null : 'لسه بيطبع غير ١٥. السطر جوه الحلقة بيحط ر مكان مجموع. لازم يزوّد: مجموع = مجموع + ر'; }},
{id:29,title:"الدوال التكرارية: برج هانوي",text:`<p>في لعبة برج هانوي عندك ن قرص وعايز تنقلهم لعمود تاني. السر: انقل ن-١ قرص بعيد، انقل القرص الكبير (حركة واحدة)، وبعدين رجّع الـ ن-١ فوقه. يعني:</p>
<pre>عدد_الحركات(ن) = ٢ × عدد_الحركات(ن - ١) + ١</pre>
<p>ودي بالظبط دالة بتنادي نفسها. لازم لها <b>حالة وقوف</b>: لو ن == ٠ مفيش حركات.</p>
<p><b>مهمتك:</b> كمّل الدالة <code>حركات</code> عشان تحسب عدد الحركات. الأسطر اللي تحتها بتجرّبها على ٣ أقراص (٧) و١٠ أقراص (١٠٢٣).</p>`,
starter:'دالة حركات(ن) {\n  # حالة الوقوف: لو ن == ٠ ارجع ٠\n  # وإلا ارجع ٢ * حركات(ن - ١) + ١\n}\nاطبع حركات(٣)\nاطبع حركات(١٠)',
check(out){ return out.join('|')==='7|1023' ? null : 'المفروض يطبع ٧ ثم ١٠٢٣. ابدأ بـ لو ن == ٠ { ارجع ٠ } وبعدها ارجع ٢ * حركات(ن - ١) + ١'; }},
{id:30,title:"قايمة قواميس: داتا حقيقية",text:`<p>الداتا الحقيقية غالباً قايمة من القواميس: كل عنصر فيه بيانات عن حاجة. زي أسئلة مسابقة المعلومات بالظبط:</p>
<pre>خلي منتجات = [
  {اسم: "قلم"، سعر: ١٠}،
  {اسم: "كتاب"، سعر: ٣٠}
]
لكل م في منتجات {
  اطبع م.اسم + " بـ " + م.سعر
}</pre>
<p>الـ <code>م.اسم</code> بتجيب خاصية من القاموس. وتقدر تقارن وتفتكر زي ما عملت مع الأرقام.</p>
<p><b>مهمتك:</b> اطبع اسم المنتج <b>الأغلى</b> بس (الناتج: حقيبة). لف على القايمة وفتكر الأغلى سعر واسمه.</p>`,
starter:'خلي منتجات = [\n  {اسم: "قلم"، سعر: ١٠}،\n  {اسم: "حقيبة"، سعر: ٢٥٠}،\n  {اسم: "كتاب"، سعر: ٣٠}\n]\n# لف وفتكر الأغلى',
check(out){ return out.length===1 && out[0]==='حقيبة' ? null : 'المفروض يطبع اسم الأغلى بس: حقيبة. فتكر أغلى سعر في متغير واسم صاحبه، واطبع الاسم بعد الحلقة.'; }},
{id:31,title:"تحليل الخريطة: عد الجدران",text:`<p>الخريطة في ألعاب كتير هي قايمة صفوف نصية: كل <code>#</code> جدار وكل <code>.</code> أرض. وأمر <code>خريطة_بلاط(خريطة، ٤٠)</code> بيرسمها. بس قبل الرسم، تقدر تحلل الخريطة بحلقتين: واحدة على الصفوف وواحدة على حروف كل صف.</p>
<pre>خلي خريطة = [
  "#####",
  "#.#.#",
  "#####"
]
لكل صف في خريطة {
  لكل حرف في صف {
    لو حرف == "#" { اطبع "جدار" }
  }
}</pre>
<p><b>مهمتك:</b> عد الجدران <b>كلها</b> في الخريطة واطبع العدد بس (الناتج: ٢٢). استخدم متغير عداد وحلقتين متداخلتين.</p>`,
starter:'خلي خريطة = [\n  "#######",\n  "#..#..#",\n  "#.....#",\n  "#..#..#",\n  "#######"\n]\n# عد الـ # كلها\n',
check(out){ return out.length===1 && String(out[0])==='22' ? null : 'المفروض يطبع عدد الجدران بس: ٢٢. اعمل عداد قبل الحلقتين، وزوّده كل ما حرف == "#"، واطبعه بعد الحلقات.'; }},
{id:32,title:"دوال الخريطة: مين حوالي؟",text:`<p>في ألعاب الخرائط، السؤال الأهم: <b>هل أقدر أمشي في الخانة دي؟</b> الدالة دي بتجاوب، وبتحمي نفسها من الخروج برا الخريطة:</p>
<pre>دالة فاضي(خ، ص، س) {
  لو ص < ٠ أو ص >= طول(خ) { ارجع غلط }
  لو س < ٠ أو س >= طول(خ[ص]) { ارجع غلط }
  ارجع خ[ص][س] == "."
}</pre>
<p>الـ <code>خ[ص][س]</code> بتجيب الحرف في الصف <code>ص</code> والعمود <code>س</code> (العد بيبدأ من ٠).</p>
<p><b>مهمتك:</b> اكتب دالة <code>جيران(خ، ص، س)</code> بترجّع كام خانة فاضية حوالين الخانة (فوق وتحت ويمين وشمال)، وبعدين اطبع <code>جيران(خريطة، ٢، ٢)</code> (الناتج: ٣). استخدم <code>فاضي</code> أربع مرات.</p>`,
starter:'خلي خريطة = [\n  "#####",\n  "#...#",\n  "#...#",\n  "#.#.#",\n  "#####"\n]\nدالة فاضي(خ، ص، س) {\n  لو ص < ٠ أو ص >= طول(خ) { ارجع غلط }\n  لو س < ٠ أو س >= طول(خ[ص]) { ارجع غلط }\n  ارجع خ[ص][س] == "."\n}\n# اكتب دالة جيران هنا\n',
check(out){ return out.length===1 && String(out[0])==='3' ? null : 'المفروض يطبع ٣ بس. جيران بتعد الخانات الفاضية الأربعة حوالين (٢، ٢): استخدم فاضي(خ، ص - ١، س) وفاضي(خ، ص + ١، س) وفاضي(خ، ص، س - ١) وفاضي(خ، ص، س + ١) وارجع العدد.'; }},
{id:33,title:'مشروع: مسك النجوم',text:`<p>هنبني لعبة <b>مسك النجوم</b>: نجمة بتقع من فوق وإنت بتحرّك سلة بالماوس. قلب اللعبة سؤال واحد: <b>السلة مسكت النجمة ولا لأ؟</b> النجمة بتتمسك لما تكون:</p>
<ul><li>قريبة من السلة أفقياً (الفرق أقل من ٦٠)</li><li>وصلت لمستوى السلة (<code>ص > ٢٤٠</code>)</li></ul>
<p>الفرق من غير ما تهتم باتجاهه بتاخده بـ <code>مطلق(س_نجمة - س_سلة)</code>، والشرطين مع بعض بـ <code>و</code>.</p>
<p><b>مهمتك:</b> كمّل دالة <code>أمسكت</code> بحيث ترجّع <b>١</b> لو اتمسكت و<b>٠</b> لو لأ. المفروض الأسطر التلاتة تطبع: ١ ثم ٠ ثم ٠.</p>
<p>بعد ما تنجح، افتح مثال «🪙 صيد العملات» أو «🧱 كسّر الطوب» وشوف نفس الفكرة جوه لعبة كاملة.</p>`,
starter:'دالة أمسكت(س_نجمة، ص_نجمة، س_سلة) {\n  # لو النجمة قريبة وواصلة، ارجع ١\n  ارجع ٠\n}\nاطبع أمسكت(١٠، ٢٥٠، ٠)\nاطبع أمسكت(٢٠٠، ٢٥٠، ٠)\nاطبع أمسكت(٥٠، ١٠٠، ٤٠)\n',
check(out){ return out.join('|')==='1|0|0' ? null : 'المفروض تطبع ١ ثم ٠ ثم ٠. جرب: لو مطلق(س_نجمة - س_سلة) < ٦٠ و ص_نجمة > ٢٤٠ { ارجع ١ }'; }},
{id:34,title:'الجداول: قايمة جوه قايمة',text:`<p>القايمة ممكن تحط جواها قوايم تانية: ده اسمه <b>جدول</b> (زي الشطرنج والخرائط). كل قايمة صغيرة هي صف.</p>
<pre>خلي جدول = [
  [١، ٢، ٣]،
  [٤، ٥، ٦]
]
اطبع جدول[١][٠]   # الصف التاني، العمود الأول: ٤</pre>
<p>الرقم الأول بيختار الصف والتاني بيختار العمود، والعد بيبدأ من ٠. وعشان تلف على أرقام من ٠، استخدم <code>كرر ٣، م {</code> واستخدم <code>م - ١</code> لأن م بيبدأ من ١.</p>
<p><b>مهمتك:</b> اجمع القُطر الرئيسي للجدول (١ + ٥ + ٩) واطبع الناتج (١٥).</p>`,
starter:'خلي جدول = [\n  [١، ٢، ٣]،\n  [٤، ٥، ٦]،\n  [٧، ٨، ٩]\n]\n# اجمع جدول[٠][٠] + جدول[١][١] + جدول[٢][٢] بحلقة\n',
check(out){ return out.length===1 && String(out[0])==='15' ? null : 'المفروض يطبع ١٥. اعمل متغير مجموع، وكرر ٣، م { مجموع = مجموع + جدول[م - ١][م - ١] } واطبعه بعد الحلقة.'; }}
,
{id:35,title:'النصوص: عد الحروف',text:`<p>النص زي القايمة: كل حرف ليه مكان، والعد بيبدأ من ٠. <code>طول(نص)</code> بيرجّع عدد الحروف و<code>نص[٠]</code> بيرجّع أول حرف.</p>
<pre>خلي كلمة = "برمجة"
اطبع كلمة[٠]        # ب
اطبع طول(كلمة)      # ٥</pre>
<p>تقدر تلف على كل حرف بـ <code>كرر طول(كلمة)، م {</code> وتستخدم <code>كلمة[م - ١]</code> لأن م بيبدأ من ١.</p>
<p><b>مهمتك:</b> عُدّ كام مرة ظهر حرف «ا» في الجملة، واطبع العدد (٣).</p>`,
starter:'خلي جملة = "مرحبا بالعالم"\nخلي عدد = ٠\n# لف على كل حرف، ولو لقيت "ا" زوّد عدد\n',
check(out){ return out.length===1 && String(out[0])==='3' ? null : 'المفروض يطبع ٣. جرب: كرر طول(جملة)، م { لو جملة[م - ١] == "ا" { عدد = عدد + ١ } } ثم اطبع عدد بعد الحلقة.'; }},
{id:36,title:'النصوص: اعكس الكلمة',text:`<p>تقدر تبني نص جديد حرف حرف بالجمع: <code>نتيجة = نتيجة + حرف</code>. لو حطيت الحرف <b>قبل</b> النتيجة بدل بعدها، الترتيب بيتعكس.</p>
<pre>خلي ناتج = ""
ناتج = "ب" + ناتج
ناتج = "ر" + ناتج
اطبع ناتج   # رب</pre>
<p><b>مهمتك:</b> اعكس كلمة «برمجة» واطبعها معكوسة (ةجمرب).</p>`,
starter:'خلي كلمة = "برمجة"\nخلي معكوس = ""\n# لف على الحروف وحط كل حرف قبل المعكوس\n',
check(out){ return out.length===1 && String(out[0])==='ةجمرب' ? null : 'المفروض يطبع ةجمرب. جرب: كرر طول(كلمة)، م { معكوس = كلمة[م - ١] + معكوس } ثم اطبع معكوس.'; }},
{id:37,title:'القواميس: عدّاد التكرار',text:`<p>القاموس بيربط <b>مفتاح</b> بقيمة: <code>عد["تفاح"] = ٣</code>. لو المفتاح مش موجود، قيمته <code>فراغ</code>، وده بيخليك تعرف إنه أول مرة تشوفه.</p>
<pre>خلي عد = {}
عد["س"] = ١
عد["س"] = عد["س"] + ١
اطبع عد["س"]    # ٢
اطبع عد["ص"] == فراغ   # صح</pre>
<p><b>مهمتك:</b> عُدّ كل فاكهة في القايمة بقاموس، واطبع عدد «تفاح» ثم عدد «موز» (٣ ثم ٢).</p>`,
starter:'خلي فواكه = ["تفاح"، "موز"، "تفاح"، "برتقال"، "تفاح"، "موز"]\nخلي عد = {}\n# لكل فاكهة: لو عد[ف] == فراغ خليها ١ وإلا زوّد ١\n',
check(out){ return out.length===2 && String(out[0])==='3' && String(out[1])==='2' ? null : 'المفروض يطبع ٣ ثم ٢ (كل رقم في سطر). جرب: لكل ف في فواكه { لو عد[ف] == فراغ { عد[ف] = ١ } وإلا { عد[ف] = عد[ف] + ١ } } ثم اطبع عد["تفاح"] واطبع عد["موز"].'; }},
{id:38,title:'الترتيب: رتب_حسب',text:`<p>عشان ترتب قايمة قواميس (طلاب مثلاً) من الأصغر للأكبر، استخدم <code>رتب_حسب(قايمة، دالة)</code>. الدالة بتاخد العنصر وترجّع القيمة اللي هنرتب بيها.</p>
<pre>خلي مرتبين = رتب_حسب(طلاب، دالة(ط) { ارجع ط.درجة })
اطبع مرتبين[٠].اسم        # صاحب أقل درجة
اطبع آخر(مرتبين).اسم       # صاحب أعلى درجة</pre>
<p><b>مهمتك:</b> رتّب الطلاب حسب الدرجة واطبع اسم صاحب أقل درجة ثم اسم صاحب أعلى درجة (أحمد ثم منى).</p>`,
starter:'خلي طلاب = [\n  {اسم: "منى"، درجة: ٩٢}،\n  {اسم: "أحمد"، درجة: ٧٨}،\n  {اسم: "كريم"، درجة: ٨٥}\n]\n# رتبهم حسب الدرجة بـ رتب_حسب واطبع أول واحد وآخر واحد\n',
check(out){ return out.length===2 && out[0]==='أحمد' && out[1]==='منى' ? null : 'المفروض يطبع أحمد ثم منى (كل اسم في سطر). جرب: خلي مرتبين = رتب_حسب(طلاب، دالة(ط) { ارجع ط.درجة }) ثم اطبع مرتبين[٠].اسم واطبع آخر(مرتبين).اسم.'; }},
{id:39,title:'البحث في القوايم: جد وأي وكل',text:`<p>٣ دوال بتسألك أسئلة عن قايمة من غير حلقة: <code>جد(قايمة، دالة)</code> بترجّع <b>أول عنصر</b> يحقق الشرط، <code>أي(...)</code> بترجّع صح لو <b>واحد على الأقل</b> حقق الشرط، و<code>كل(...)</code> بترجّع صح لو <b>كلهم</b> حققوه.</p>
<pre>خلي أعمار = [١٢، ١٩، ٣٣]
اطبع جد(أعمار، دالة(ع) { ارجع ع >= ١٨ })   # ١٩
اطبع أي(أعمار، دالة(ع) { ارجع ع > ٥٠ })    # غلط
اطبع كل(أعمار، دالة(ع) { ارجع ع > ١٠ })    # صحيح</pre>
<p><b>مهمتك:</b> في قايمة الأسعار، اطبع أول سعر فوق ١٠٠ (١٢٠)، ثم هل في سعر فوق ٢٥٠؟ (صحيح)، ثم هل كل الأسعار فوق ٥٠؟ (غلط).</p>`,
starter:'خلي أسعار = [٤٥، ١٢٠، ٨٠، ٣٠٠، ٦٠]\n# اطبع ٣ أسطر: جد، ثم أي، ثم كل\n',
check(out){ return out.length===3 && String(out[0])==='120' && out[1]==='صحيح' && out[2]==='غلط' ? null : 'المفروض يطبع ٣ أسطر: ١٢٠ ثم صحيح ثم غلط. جرب: اطبع جد(أسعار، دالة(س) { ارجع س > ١٠٠ }) وبعدها أي(أسعار، دالة(س) { ارجع س > ٢٥٠ }) وبعدها كل(أسعار، دالة(س) { ارجع س > ٥٠ }).'; }},
{id:40,title:'القواميس: لف على المفاتيح',text:`<p>الدالة <code>مفاتيح(قاموس)</code> بترجّع قايمة بكل أسماء الخانات. تقدر تلف عليها بـ <code>لكل</code> وتجيب القيمة بـ <code>قاموس[مفتاح]</code>.</p>
<pre>خلي عمر = {أحمد: ١٠، منى: ١٢}
لكل اسم في مفاتيح(عمر) {
  اطبع اسم + ": " + عمر[اسم]
}
اطبع طول(مفاتيح(عمر))   # ٢</pre>
<p><b>مهمتك:</b> في سلة الفاكهة، اطبع عدد الأنواع (٣) ثم مجموع كل القطع (١٠).</p>`,
starter:'خلي سلة = {تفاح: ٣، موز: ٢، برتقال: ٥}\nخلي مجموع = ٠\n# لف على مفاتيح(سلة) واجمع القيم، ثم اطبع عدد الأنواع ثم المجموع\n',
check(out){ return out.length===2 && String(out[0])==='3' && String(out[1])==='10' ? null : 'المفروض يطبع ٣ ثم ١٠ (كل رقم في سطر). جرب: لكل ك في مفاتيح(سلة) { مجموع = مجموع + سلة[ك] } ثم اطبع طول(مفاتيح(سلة)) واطبع مجموع.'; }},
{id:41,title:'تنضيف النص: بدل وفصل',text:`<p><code>بدل(نص، القديم، الجديد)</code> بتغيّر كل ظهور لجزء في النص. و<code>فصل(نص، فاصل)</code> بتقطّع النص لقايمة كلمات.</p>
<pre>خلي ن = "أ-ب-ج"
اطبع بدل(ن، "-"، "،")        # أ،ب،ج
اطبع طول(فصل(ن، "-"))       # ٣</pre>
<p><b>مهمتك:</b> بدّل الشرطات في النص بمسافات واطبع النتيجة، وبعدها اطبع عدد الكلمات (٤).</p>`,
starter:'خلي ملف = "اسكندرية-القاهرة-أسوان-الأقصر"\n# بدل الشرطات بمسافات، اطبعه، ثم اطبع عدد الكلمات\n',
check(out){ return out.length===2 && out[0]==='اسكندرية القاهرة أسوان الأقصر' && String(out[1])==='4' ? null : 'المفروض سطرين: اسكندرية القاهرة أسوان الأقصر ثم ٤. جرب: خلي نظيف = بدل(ملف، "-"، " ") واطبعه، ثم اطبع طول(فصل(نظيف، " ")).'; }}
];
