window.BARMEJ_EXAMPLES.push(
{title:'🏰 مغامرة الكهف',desc:'اختار: قصة تفاعلية بأزرار اختيار!',code:'اطبع "🏰 مغامرة الكهف"\nاطبع "— — —"\nخلي بطل = اسأل("اسم البطل؟")\nخلي طريق = اختار("قدامك طريقين يا " + بطل + " — تروح فين؟"، ["الكهف المضيء"، "النفق المظلم"])\nلو طريق == "الكهف المضيء" {\n  اطبع "لقيت كنز من الدهب! 💰"\n  خلي كنز = اختار("تاخد إيه من الكنز؟"، ["تاج ذهبي"، "سيف سحري"، "خريطة كنوز"])\n  اطبع "خرجت من المغامرة ومعاك: " + كنز + " 🏆"\n} وإلا {\n  خلي شجاعة = اختار("سمعت صوت غريب… تعمل إيه؟"، ["أكمل بشجاعة"، "أرجع بسرعة"])\n  لو شجاعة == "أكمل بشجاعة" {\n    اطبع "الصوت كان قطة صغيرة ضايعة 🐱 — رجعتها لصاحبها وكسبت مكافأة!"\n  } وإلا {\n    اطبع "رجعت بسلامة… المغامرة تكمل مرة تانية! 🌙"\n  }\n}\nاطبع "النهاية — جرّب اختيارات تانية! 🎭"'}
);
window.BARMEJ_EXAMPLES.push(
{title:'🕐 ساعة حائط',desc:'جيب وجتا وساعات: ساعة حقيقية شغالة!',code:'# 🕐 ساعة حائط حية — بتتحدث كل ثانية\nدالة عقرب(زاوية، طول، س، ل) {\n  لون(ل)\n  سمك(س)\n  ارفع()\n  اذهب(٠، ٠)\n  انزل()\n  يمين(زاوية)\n  قدم(طول)\n  ورا(طول)\n  شمال(زاوية)\n}\nاطبع "🕐 الساعة شغالة لمدة دقيقة…"\nكرر ٦٠ {\n  امسح_اللوحة()\n  لون("ذهبي")\n  سمك(٤)\n  ارفع()\n  اذهب(٠، ٠)\n  انزل()\n  دائرة(٢٣٠)\n  كرر ١٢ {\n    ارفع()\n    خلي ز = عداد * ٣٠\n    اذهب(جيب(ز) * ٢٠٠، -جتا(ز) * ٢٠٠)\n    انزل()\n    لون("أبيض")\n    نقطة(٨)\n  }\n  خلي ث = ثواني()\n  خلي د = دقائق() + ث / ٦٠\n  خلي س = (ساعات() % ١٢) + د / ٦٠\n  عقرب(س * ٣٠، ١١٠، ٨، "أبيض")\n  عقرب(د * ٦، ١٧٠، ٥، "سماوي")\n  عقرب(ث * ٦، ١٩٠، ٢، "أحمر")\n  لون("ذهبي")\n  ارفع()\n  اذهب(٠، ٠)\n  نقطة(١٢)\n  استنى(١٠٠٠)\n}\nاطبع "خلصت الدقيقة ⏰"'}
);
window.BARMEJ_EXAMPLES.push(
{title:'🧠 اختبار المعلومات',desc:'اختار وقوائم: كويز بأسئلة ونتيجة!',code:'# 🧠 كويز المعلومات العامة\nخلي أسئلة = [\n  {س: "أكبر كوكب في المجموعة الشمسية؟"، ج: ["المشترى"، "المريخ"، "الأرض"]، إج: "المشترى"}،\n  {س: "كم عدد أرجل العنكبوت؟"، ج: ["٨"، "٦"، "١٠"]، إج: "٨"}،\n  {س: "عاصمة مصر؟"، ج: ["القاهرة"، "الإسكندرية"، "الجيزة"]، إج: "القاهرة"}،\n  {س: "أطول نهر في العالم؟"، ج: ["النيل"، "الأمازون"، "الفرات"]، إج: "النيل"}\n]\nخلي نقاط = ٠\nاطبع "🧠 اختبار المعلومات — ٤ أسئلة!"\nلكل سؤال في أسئلة {\n  خلي رد = اختار(سؤال.س، سؤال.ج)\n  لو رد == سؤال.إج {\n    نقاط = نقاط + ١\n    اطبع "✔ صح! أحسنت"\n    نغمة("صول")\n  } وإلا {\n    اطبع "✖ غلط — الصح: " + سؤال.إج\n    نغمة("ري")\n  }\n}\nاطبع "— — —"\nاطبع "نتيجتك: " + نقاط + " من " + طول(أسئلة)\nلو نقاط == طول(أسئلة) {\n  اطبع "🏆 علامة كاملة! عبقري!"\n} وإلا لو نقاط >= ٢ {\n  اطبع "👍 كويس جدًا!"\n} وإلا {\n  اطبع "💪 حاول تاني!"\n}'}
);

window.BARMEJ_EXAMPLES.push(
{title:'\u{1F3AF} \u062E\u0645\u0651\u0646 \u0627\u0644\u0643\u0644\u0645\u0629',desc:'\u0646\u0635\u0648\u0635 \u0648\u0639\u0634\u0648\u0627\u0626\u064A: \u0644\u0639\u0628\u0629 \u062A\u062E\u0645\u064A\u0646 \u0627\u0644\u0643\u0644\u0645\u0629 \u062D\u0631\u0641 \u0628\u062D\u0631\u0641!',code:'# \u{1F3AF} \u062E\u0645\u0651\u0646 \u0627\u0644\u0643\u0644\u0645\u0629 \u2014 \u0644\u0639\u0628\u0629 \u0627\u0644\u062D\u0631\u0648\u0641\n\u062E\u0644\u064A \u0643\u0644\u0645\u0627\u062A = ["\u0628\u0631\u0645\u062C\u0629"\u060C "\u0645\u062F\u0631\u0633\u0629"\u060C "\u0643\u0645\u0628\u064A\u0648\u062A\u0631"\u060C "\u0642\u0645\u0631"\u060C "\u0643\u062A\u0627\u0628"\u060C "\u0634\u0645\u0633"]\n\u062E\u0644\u064A \u0643\u0644\u0645\u0629 = \u0639\u0634\u0648\u0627\u0626\u064A(\u0643\u0644\u0645\u0627\u062A)\n\u062E\u0644\u064A \u0645\u062E\u0641\u064A = ""\n\u0643\u0631\u0631 \u0637\u0648\u0644(\u0643\u0644\u0645\u0629) {\n  \u0645\u062E\u0641\u064A = \u0645\u062E\u0641\u064A + "\u2B1C"\n}\n\u062E\u0644\u064A \u0645\u062D\u0627\u0648\u0644\u0627\u062A = \u0666\n\u0627\u0637\u0628\u0639 "\u{1F3AF} \u062E\u0645\u0651\u0646 \u0627\u0644\u0643\u0644\u0645\u0629! \u0639\u0646\u062F\u0643 \u0666 \u0645\u062D\u0627\u0648\u0644\u0627\u062A"\n\u0637\u0627\u0644\u0645\u0627 \u0645\u062D\u0627\u0648\u0644\u0627\u062A > \u0660 \u0648 \u064A\u062D\u062A\u0648\u064A(\u0645\u062E\u0641\u064A\u060C "\u2B1C") {\n  \u0627\u0637\u0628\u0639 "\u0627\u0644\u0643\u0644\u0645\u0629: " + \u0645\u062E\u0641\u064A\n  \u062E\u0644\u064A \u062D\u0631\u0641 = \u0627\u0633\u0623\u0644("\u062E\u0645\u0651\u0646 \u062D\u0631\u0641:")\n  \u062E\u0644\u064A \u0644\u0642\u064A\u062A = \u063A\u0644\u0637\n  \u062E\u0644\u064A \u062C\u062F\u064A\u062F = ""\n  \u0643\u0631\u0631 \u0637\u0648\u0644(\u0643\u0644\u0645\u0629) \u060C i {\n    \u0644\u0648 \u0643\u0644\u0645\u0629[i - \u0661] == \u062D\u0631\u0641 {\n      \u062C\u062F\u064A\u062F = \u062C\u062F\u064A\u062F + \u062D\u0631\u0641\n      \u0644\u0642\u064A\u062A = \u0635\u062D\n    } \u0648\u0625\u0644\u0627 {\n      \u062C\u062F\u064A\u062F = \u062C\u062F\u064A\u062F + \u0645\u062E\u0641\u064A[i - \u0661]\n    }\n  }\n  \u0645\u062E\u0641\u064A = \u062C\u062F\u064A\u062F\n  \u0644\u0648 \u0644\u0642\u064A\u062A {\n    \u0627\u0637\u0628\u0639 "\u2714 \u062D\u0631\u0641 \u0635\u062D!"\n    \u0646\u063A\u0645\u0629("\u0635\u0648\u0644")\n  } \u0648\u0625\u0644\u0627 {\n    \u0645\u062D\u0627\u0648\u0644\u0627\u062A = \u0645\u062D\u0627\u0648\u0644\u0627\u062A - \u0661\n    \u0627\u0637\u0628\u0639 "\u2716 \u0645\u0634 \u0645\u0648\u062C\u0648\u062F \u2014 \u0628\u0627\u0642\u064A " + \u0645\u062D\u0627\u0648\u0644\u0627\u062A\n    \u0646\u063A\u0645\u0629("\u0631\u064A")\n  }\n}\n\u0644\u0648 \u064A\u062D\u062A\u0648\u064A(\u0645\u062E\u0641\u064A\u060C "\u2B1C") {\n  \u0627\u0637\u0628\u0639 "\u{1F480} \u062E\u0633\u0631\u062A! \u0627\u0644\u0643\u0644\u0645\u0629 \u0643\u0627\u0646\u062A: " + \u0643\u0644\u0645\u0629\n} \u0648\u0625\u0644\u0627 {\n  \u0627\u0637\u0628\u0639 "\u{1F389} \u0645\u0628\u0631\u0648\u0643! \u062E\u0645\u0651\u0646\u062A\u0647\u0627: " + \u0643\u0644\u0645\u0629\n}'}
);

