window.BARMEJ_EXAMPLES.push(
{title:'⚔️ معركة الوحوش',desc:'أصناف ووراثة: ساحر ضد تنين في معركة بالأدوار.',code:"# ⚔️ معركة الوحوش — أصناف ووراثة\nصنف مقاتل {\n  دالة بناء(اسم، دم، قوة) {\n    هذا.اسم = اسم\n    هذا.دم = دم\n    هذا.قوة = قوة\n  }\n  دالة حي() { ارجع هذا.دم > ٠ }\n  دالة اضرب(خصم) {\n    خلي ضربة = عشوائي(١، هذا.قوة)\n    خصم.دم = خصم.دم - ضربة\n    اطبع هذا.اسم + \" ضرب \" + خصم.اسم + \" بـ \" + ضربة + \" (باقي \" + أكبر(خصم.دم، ٠) + \")\"\n  }\n}\nصنف ساحر يرث مقاتل {\n  دالة بناء(اسم) { الأب.بناء(اسم، ٣٠، ٨) }\n  دالة اضرب(خصم) {\n    اطبع \"✨ \" + هذا.اسم + \" بيرمي تعويذة!\"\n    الأب.اضرب(خصم)\n    الأب.اضرب(خصم)\n  }\n}\nخلي أ = جديد ساحر(\"ميرلين\")\nخلي ب = جديد مقاتل(\"التنين\"، ٤٠، ١٢)\nخلي جولة = ١\nطالما أ.حي() و ب.حي() {\n  اطبع \"— جولة \" + جولة + \" —\"\n  أ.اضرب(ب)\n  لو ب.حي() { ب.اضرب(أ) }\n  جولة = جولة + ١\n}\nلو أ.حي() { اطبع \"🏆 فاز \" + أ.اسم } وإلا { اطبع \"💀 فاز \" + ب.اسم }"},
{title:'🏦 حساب بنكي',desc:'صنف بيحفظ الرصيد: إيداع وسحب.',code:"# 🏦 حساب بنكي بصنف\nصنف حساب {\n  دالة بناء(صاحب، رصيد) {\n    هذا.صاحب = صاحب\n    هذا.رصيد = رصيد\n  }\n  دالة ايداع(مبلغ) {\n    هذا.رصيد = هذا.رصيد + مبلغ\n    اطبع \"تم إيداع \" + مبلغ + \" — الرصيد \" + هذا.رصيد\n  }\n  دالة سحب(مبلغ) {\n    لو مبلغ > هذا.رصيد {\n      اطبع \"❌ الرصيد مش كفاية يا \" + هذا.صاحب\n      ارجع غلط\n    }\n    هذا.رصيد = هذا.رصيد - مبلغ\n    اطبع \"تم سحب \" + مبلغ + \" — الرصيد \" + هذا.رصيد\n    ارجع صح\n  }\n}\nخلي ح = جديد حساب(\"منى\"، ١٠٠٠)\nح.ايداع(٥٠٠)\nح.سحب(٢٠٠٠)\nح.سحب(٧٥٠)\nاطبع ح"}
);

window.BARMEJ_EXAMPLES.push(
{title:'🎓 خط إنتاج الدرجات',desc:'خريطة وصفّي واختزل ورتب_حسب: تحليل بيانات في أسطر قليلة.',code:"# 🎓 خط إنتاج الدرجات — دوال بتاخد دوال\nخلي طلاب = [\n  {اسم: \"أحمد\"، درجة: ٨٥}،\n  {اسم: \"منى\"، درجة: ٩٢}،\n  {اسم: \"كريم\"، درجة: ٦١}،\n  {اسم: \"ليلى\"، درجة: ٧٨}،\n  {اسم: \"عمر\"، درجة: ٤٩}\n]\nخلي ناجحين = صفّي(طلاب، دالة(ط): ط.درجة >= ٥٠)\nاطبع \"الناجحين: \" + وصل(خريطة(ناجحين، دالة(ط): ط.اسم)، \"، \")\nخلي مجموع_الدرجات = اختزل(خريطة(طلاب، دالة(ط): ط.درجة)، دالة(أ، ب): أ + ب، ٠)\nاطبع \"المتوسط: \" + قرب(مجموع_الدرجات / طول(طلاب)، ١)\nخلي ترتيب = رتب_حسب(طلاب، دالة(ط): ط.درجة، \"تنازلي\")\nاطبع \"— الترتيب —\"\nلكل ط في ترتيب {\n  اطبع ط.اسم + \": \" + ط.درجة\n}\nخلي أول_راسب = جد(طلاب، دالة(ط): ط.درجة < ٥٠)\nاطبع \"أول راسب: \" + أول_راسب.اسم\nاطبع \"الكل فوق ٤٠؟ \" + كل(طلاب، دالة(ط): ط.درجة > ٤٠)"},
{title:'🔢 أولية ومربعات',desc:'دوال بتاخد وبترجّع دوال: الأعداد الأولية وتركيب الدوال.',code:"# 🔢 الأعداد الأولية بدوال متقدمة\nخلي أولي = دالة(ن) {\n  لو ن < ٢ { ارجع غلط }\n  ارجع كل(مدى(٢، ن - ١)، دالة(د): ن % د != ٠ أو د == ن)\n}\nاطبع \"الأولية لحد ٥٠:\"\nاطبع وصل(صفّي(مدى(١، ٥٠)، أولي)، \" \")\nخلي مربعات = خريطة(مدى(١، ٩)، دالة(س): س * س)\nاطبع \"المربعات: \" + وصل(مربعات، \"، \")\nخلي ضاعف = دالة(د) { ارجع دالة(س): د(د(س)) }\nخلي زود٣ = دالة(س): س + ٣\nاطبع \"زود٣ مرتين على ١٠: \" + ضاعف(زود٣)(١٠)"}
);

window.BARMEJ_EXAMPLES.push(
{title:'🎯 اضرب الهدف',desc:'لعبة بالماوس أو اللمس: اضغط على الدايرة الحمرا قبل ما تختفي.',code:"# 🎯 اضرب الهدف — اضغط على الدايرة قبل ما تختفي!\nخلي نقاط = ٠\nخلي فات = ٠\nخلي هدف_س = ٠\nخلي هدف_ص = ٠\nخلي عمر = ٠\nاطبع \"🎯 اضغط (أو المس) الدايرة الحمرا. ٣ فرص بس!\"\nطالما فات < ٣ {\n  لو عمر <= ٠ {\n    هدف_س = عشوائي(-٢٢٠، ٢٢٠)\n    هدف_ص = عشوائي(-٢٢٠، ٢٢٠)\n    عمر = ٧٠\n  }\n  خلي ض = نقرة()\n  لو ض != فراغ {\n    لو جذر((ض[٠] - هدف_س) ^ ٢ + (ض[١] - هدف_ص) ^ ٢) < ٣٥ {\n      نقاط = نقاط + ١\n      نغمة(\"صول\")\n      عمر = ٠\n    } وإلا {\n      فات = فات + ١\n      نغمة(\"ري\")\n      اطبع \"❌ غلط! باقي \" + (٣ - فات)\n    }\n  } وإلا لو عمر == ١ {\n    فات = فات + ١\n    اطبع \"⌛ فاتك الهدف! باقي \" + (٣ - فات)\n  }\n  عمر = عمر - ١\n  امسح_اللوحة()\n  ارفع()\n  اذهب(هدف_س، هدف_ص)\n  لون(\"أحمر\")\n  نقطة(٧٠)\n  ارفع()\n  اذهب(٠، -٢٧٠)\n  لون(\"ذهبي\")\n  نص_على_اللوحة(\"نقاط: \" + نقاط، ٢٤)\n  استنى(٣٠)\n}\nاطبع \"خلصت! نقاطك: \" + نقاط + \" 🏁\""},
{title:'🎨 لوحة الرسم',desc:'ارسم بالماوس أو بإصبعك، واللون بيتغير مع كل ضغطة.',code:"# 🎨 لوحة الرسم — ارسم بإصبعك أو بالماوس\n# كل ما تضغط: النقطة بتتلون بلون مختلف\nخلي ألوان = [\"أحمر\"، \"برتقالي\"، \"أخضر\"، \"أزرق\"، \"بنفسجي\"، \"ذهبي\"]\nخلي رقم_اللون = ٠\nخلي كان_مضغوط = غلط\nاطبع \"🎨 اضغط واسحب على اللوحة. اضغط مرتين لتغيير اللون.\"\nطالما صح {\n  لو ماوس_مضغوط() {\n    لو مش كان_مضغوط { رقم_اللون = (رقم_اللون + ١) % طول(ألوان) }\n    ارفع()\n    اذهب(ماوس_س()، ماوس_ص())\n    لون(ألوان[رقم_اللون])\n    نقطة(١٦)\n  }\n  كان_مضغوط = ماوس_مضغوط()\n  استنى(١٠)\n}"}
);

window.BARMEJ_EXAMPLES.push(
{title:'🧰 صندوق الأدوات',desc:'مكتبات جاهزة بـ استورد: رياضيات ونصوص وقوائم.',code:"# 🧰 صندوق الأدوات — مكتبات جاهزة\nاستورد \"رياضيات\"\nاستورد \"نصوص\"\nاستورد \"قوائم\"\nاطبع \"٥! = \" + مضروب(٥)\nاطبع \"أكبر قاسم مشترك لـ ٤٨ و ١٨: \" + قاسم_مشترك(٤٨، ١٨)\nاطبع \"الأولية لحد ٤٠: \" + وصل(صفّي(مدى(١، ٤٠)، أولي)، \" \")\nاطبع \"فيبوناتشي(١٥) = \" + فيبوناتشي(١٥)\nاطبع \"الوسيط: \" + وسيط([٧، ١، ٣، ٩، ٥])\nاطبع \"— نصوص —\"\nخلي جملة = \"البرمجة بالعربي ممتعة جدا\"\nاطبع \"كلمات: \" + عدد_الكلمات(جملة) + \"، الأطول: \" + أطول_كلمة(جملة)\nاطبع \"هل «ملم» متناظرة؟ \" + متناظر(\"ملم\")\nاطبع \"— قوائم —\"\nاطبع مجموعات(مدى(١، ٧)، ٣)\nاطبع تسطيح([١، [٢، [٣، [٤]]]، ٥])\nاطبع تقاطع([١، ٢، ٣، ٤]، [٣، ٤، ٥])"}
);
window.BARMEJ_EXAMPLES.push(
{title:'🌟 مطاردة النجوم',desc:'لعبة أكشن بالماوس/اللمس: اجمع النجوم وهرب من العدو اللي بيلاحقك.',code:"# 🌟 مطاردة النجوم — حرّك الماوس (أو إصبعك) والمركب يطاردها\n# اجمع النجوم الصفرا وابعد عن الكرات الحمرا!\nخلي مركب_س = ٠\nخلي مركب_ص = ٠\nخلي نجمة_س = ١٢٠\nخلي نجمة_ص = -٩٠\nخلي عدو_س = -٢٠٠\nخلي عدو_ص = ٢٠٠\nخلي نقاط = ٠\nخلي أرواح = ٣\nاطبع \"🌟 حرّك الماوس/اللمس. اجمع النجوم وتجنب الأحمر. ٣ أرواح!\"\nطالما أرواح > ٠ {\n  لو ماوس_مضغوط() {\n    خلي ب = مسافة(مركب_س، مركب_ص، ماوس_س()، ماوس_ص())\n    لو ب > ٦ {\n      مركب_س = مركب_س + (ماوس_س() - مركب_س) / ب * ٦\n      مركب_ص = مركب_ص + (ماوس_ص() - مركب_ص) / ب * ٦\n    }\n  }\n  # العدو بيلاحق المركب ببطء\n  خلي بع = مسافة(عدو_س، عدو_ص، مركب_س، مركب_ص)\n  لو بع > ١ {\n    عدو_س = عدو_س + (مركب_س - عدو_س) / بع * (١.٥ + نقاط * ٠.٢)\n    عدو_ص = عدو_ص + (مركب_ص - عدو_ص) / بع * (١.٥ + نقاط * ٠.٢)\n  }\n  لو تصادم(مركب_س، مركب_ص، ١٥، نجمة_س، نجمة_ص، ١٢) {\n    نقاط = نقاط + ١\n    نغمة(\"صول\")\n    نجمة_س = عشوائي(-٢٥٠، ٢٥٠)\n    نجمة_ص = عشوائي(-٢٥٠، ٢٥٠)\n  }\n  لو تصادم(مركب_س، مركب_ص، ١٥، عدو_س، عدو_ص، ٢٢) {\n    أرواح = أرواح - ١\n    نغمة(\"ري\")\n    عدو_س = عشوائي(-٢٥٠، ٢٥٠)\n    عدو_ص = ٢٨٠\n  }\n  امسح_اللوحة()\n  ارفع()\n  اذهب(نجمة_س، نجمة_ص)\n  لون(\"ذهبي\")\n  نقطة(٢٤)\n  ارفع()\n  اذهب(عدو_س، عدو_ص)\n  لون(\"أحمر\")\n  نقطة(٤٤)\n  ارفع()\n  اذهب(مركب_س، مركب_ص)\n  لون(\"أخضر\")\n  نقطة(٣٠)\n  ارفع()\n  اذهب(-٤٢٠، -٢٩٠)\n  لون(\"أبيض\")\n  نص_على_اللوحة(\"نقاط: \" + نقاط + \"   أرواح: \" + أرواح، ٢٠)\n  استنى(٢٠)\n}\nاطبع \"💥 خلصت! نقاطك: \" + نقاط"}
);
